const crypto = require('crypto');
const checksumKey = 'YOUR_PAYOS_CHECKSUM_KEY'; // THAY THẾ BẰNG CHECKSUM KEY
const clientId = 'YOUR_PAYOS_CLIENT_ID'; // THAY THẾ BẰNG CLIENT ID
const apiKey = 'YOUR_PAYOS_API_KEY'; // THAY THẾ BẰNG API KEY

const discordUserId = $input.item.json.body.userId;
const amount = 50000; // 50,000 VND (PayOS dùng số tiền thực tế)

// Generate orderCode as a random number <= 9007199254740991
const orderCode = Number(String(Date.now()).slice(-9) + Math.floor(Math.random() * 1000));
const description = discordUserId; // Lưu discordUserId vào description (max 25 char)
const returnUrl = 'http://localhost:5678/webhook/payos-ipn';
const cancelUrl = 'http://localhost:5678/webhook/payos-ipn';

// Tạo signature
const signData = `amount=${amount}&cancelUrl=${cancelUrl}&description=${description}&orderCode=${orderCode}&returnUrl=${returnUrl}`;
const signature = crypto.createHmac('sha256', checksumKey).update(signData).digest('hex');

const body = {
  orderCode,
  amount,
  description,
  returnUrl,
  cancelUrl,
  signature
};

return {
  json: {
    discordUserId,
    orderCode,
    body,
    headers: {
      'x-client-id': clientId,
      'x-api-key': apiKey,
      'Content-Type': 'application/json'
    }
  }
};

const prevData = $('Build PayOS Params & Sign').first().json;
const payosData = $input.item.json.data;

const checkoutUrl = payosData.checkoutUrl;
const qrCode = payosData.qrCode;
const qrImageUrl = "https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=" + encodeURIComponent(qrCode);

return {
  json: {
    discordUserId: prevData.discordUserId,
    orderCode: prevData.orderCode,
    checkoutUrl: checkoutUrl,
    qrImageUrl: qrImageUrl
  }
};

